// OPC UA acquisition (ADR-0017): one client per OPC UA source in the model.
// Input: the list of sources from "build model cache". Output 1: one message
// per value change. Output 2: one message per source connection change.
const opcua = global.get("opcua");
if (!opcua) {
    node.error("node-opcua is not available (see nodered/settings.js)");
    return null;
}

// A new model keeps the connections of unchanged sources; changed and
// removed sources are disconnected, new and changed ones (re)connected.
const wanted = {};
for (const src of (msg.payload || [])) if (src.protocol === "opcua") wanted[src.name] = src;
const old = context.get("clients") || {};
const clients = {};
for (const [name, s] of Object.entries(old)) {
    if (wanted[name] && wanted[name].signature === s.signature) { clients[name] = s; continue; }
    try { await s.client.disconnect(); } catch (e) { /* already closed */ }
}
context.set("clients", clients);

// OPC UA guarantees the namespace URI, not its number, so the model stores
// "nsu=<uri>;s=Name" and it is translated here to "ns=<number>;s=Name".
function translate(address, namespaces) {
    const m = /^nsu=([^;]+);(.+)$/.exec(address);
    if (!m) return address;
    const index = namespaces.indexOf(m[1]);
    if (index < 0) throw new Error("namespace " + m[1] + " is not on this server");
    return "ns=" + index + ";" + m[2];
}

function report(src, state, online, error) {
    if (state.online === online) return;          // only changes
    state.online = online;
    node.send([null, { payload: { source: src.name, online, error } }]);
    node.status(online ? { fill: "green", shape: "dot", text: src.name + " online" }
                       : { fill: "red", shape: "ring", text: src.name + " offline" });
}

async function start(src) {
    const settings = src.settings || {};
    const state = { client: null, online: null, signature: src.signature };
    clients[src.name] = state;
    const client = opcua.OPCUAClient.create({
        applicationName: "OFM " + env.get("OFM_RUNTIME_NAME"),
        endpointMustExist: false,
        securityMode: opcua.MessageSecurityMode[settings.securityMode || "None"],
        securityPolicy: opcua.SecurityPolicy[settings.securityPolicy || "None"],
        connectionStrategy: { initialDelay: 1000, maxDelay: 10000, maxRetry: -1 },   // retry forever
        keepSessionAlive: true
    });
    state.client = client;
    client.on("connection_lost", () => report(src, state, false, "connection lost"));
    client.on("connection_reestablished", () => report(src, state, true));
    client.on("backoff", () => report(src, state, false, "cannot reach " + src.endpoint));

    try {
        await client.connect(src.endpoint);
        const session = await client.createSession();
        const namespaces = await session.readNamespaceArray();
        const subscription = opcua.ClientSubscription.create(session, {
            requestedPublishingInterval: settings.publishingIntervalMs || 1000,
            requestedLifetimeCount: 60,
            requestedMaxKeepAliveCount: 20,
            publishingEnabled: true
        });
        for (const item of src.items) {
            // An address the server does not have is published as v null, q bad (step 2.4).
            const refuse = (why) => {
                node.warn(src.name + ": " + item.address + ": " + why + " - not read");
                node.send([{ payload: { source: src.name, address: item.address, value: null, status: "BadNodeIdUnknown",
                                        sourceTimestamp: null, receivedAt: Date.now() } }, null]);
            };
            let nodeId;
            try {
                nodeId = translate(item.address, namespaces);
            } catch (e) {
                refuse(e.message);
                continue;
            }
            const monitored = opcua.ClientMonitoredItem.create(subscription,
                { nodeId, attributeId: opcua.AttributeIds.Value },
                { samplingInterval: settings.samplingIntervalMs || 500, discardOldest: true, queueSize: 10 },
                opcua.TimestampsToReturn.Both);
            monitored.on("changed", (dv) => node.send([{
                payload: {
                    source: src.name,
                    address: item.address,                       // as stored in the model
                    value: dv.value ? dv.value.value : null,
                    status: dv.statusCode ? dv.statusCode.name : "Bad",
                    sourceTimestamp: dv.sourceTimestamp ? dv.sourceTimestamp.getTime() : null,
                    receivedAt: Date.now()
                }
            }, null]));
            monitored.on("err", (e) => refuse(String(e)));
        }
        report(src, state, true);
    } catch (e) {
        report(src, state, false, e.message);
        node.error(src.name + ": " + e.message);
    }
}

for (const src of Object.values(wanted)) {
    if (!clients[src.name]) start(src);                   // runs in the background
}
if (Object.keys(wanted).length === 0) node.status({});
return null;

finalize:
// Close every OPC UA connection when the flow is stopped or redeployed.
const clients = context.get("clients") || {};
for (const s of Object.values(clients)) {
    s.client.disconnect().catch(() => { /* already closed */ });   // "On Stop" code cannot wait
}
context.set("clients", {});

