// Polled acquisition (ADR-0018): Siemens S7 (S7 communication, PUT/GET) and
// Rockwell Logix controllers (EtherNet/IP, tag names). One connection per
// source in the model, read every pollIntervalMs. Read-only: never writes.
// Input: the list of sources from "build model cache". Output 1: one message
// per value that changed (and every value after each (re)connection);
// republishing unchanged values is done centrally by "heartbeat" (ADR-0007).
// Output 2: one message per source connection change.
// PLCs send no timestamps, so values are stamped by this gateway (ADR-0003).
const POLLED = ["s7", "ethernetip"];
const BACKOFF_MS = [1000, 2000, 5000, 10000];         // wait before reconnecting
const OPEN_TIMEOUT_MS = 5000;

// A new model keeps the connections of unchanged sources; changed and
// removed sources are closed, new and changed ones (re)connected.
const list = (msg.payload || []).filter(s => POLLED.includes(s.protocol));
const wanted = {};
for (const src of list) wanted[src.name] = src;
const old = context.get("sources") || {};
const sources = {};
for (const [name, s] of Object.entries(old)) {
    if (wanted[name] && wanted[name].signature === s.signature) sources[name] = s;
    else s.stop();
}
context.set("sources", sources);

function showStatus() {
    const all = Object.values(context.get("sources") || {});
    const off = all.filter(s => !s.online).map(s => s.name);
    node.status(all.length === 0 ? {}
        : off.length ? { fill: "red", shape: "ring", text: "offline: " + off.join(", ") }
        : { fill: "green", shape: "dot", text: all.length + " PLC(s) online" });
}

function report(st, online, error) {
    if (st.online === online) return;                  // only changes
    st.online = online;
    node.send([null, { payload: { source: st.name, online, error } }]);
    showStatus();
}

function hostPort(endpoint, defaultPort) {
    const m = /^\s*([^:\s]+)(?::(\d+))?\s*$/.exec(String(endpoint || ""));
    if (!m) throw new Error("endpoint must be an IP address or host name, optionally :port");
    return { host: m[1], port: m[2] ? Number(m[2]) : defaultPort };
}

function withTimeout(promise, ms, what) {
    let timer;
    return Promise.race([
        promise,
        new Promise((_, reject) => { timer = setTimeout(() => reject(new Error(what + ": no answer within " + ms / 1000 + " s")), ms); })
    ]).finally(() => clearTimeout(timer));
}

function describe(e) {
    if (!e) return "unknown error";
    if (e.message) return e.message;
    if (e.generalStatusCode !== undefined) return "CIP status " + e.generalStatusCode;   // EtherNet/IP
    return String(e);
}

// One driver per protocol: open a connection; probe one address (throws if
// it cannot be read); read a list of good addresses in as few requests as
// the protocol allows.
const drivers = {
    s7: async (src, settings) => {
        const lib = global.get("s7");
        if (!lib) throw new Error("S7 library is not available (see nodered/settings.js)");
        const { host, port } = hostPort(src.endpoint, 102);
        const ep = new lib.S7Endpoint({
            host, port,
            rack: Number.isInteger(settings.rack) ? settings.rack : 0,
            slot: Number.isInteger(settings.slot) ? settings.slot : 1,
            autoReconnect: 0                                // reconnecting is done below
        });
        ep.on("error", () => { /* reported by the next read */ });
        await withTimeout(ep.connect(), OPEN_TIMEOUT_MS, "connect to " + host);
        const probeGroup = new lib.S7ItemGroup(ep);
        let group = null, groupKey = null;
        return {
            probe: async address => {
                probeGroup.addItems(address);               // throws on a malformed address
                try { await probeGroup.readAllItems(); } finally { probeGroup.removeItems(address); }
            },
            read: async addresses => {
                const key = addresses.join("\n");
                if (key !== groupKey) {
                    group = new lib.S7ItemGroup(ep);
                    group.addItems(addresses);
                    groupKey = key;
                }
                const r = await group.readAllItems();
                return addresses.map(a => r[a]);
            },
            connected: () => ep.isConnected,
            close: () => ep.disconnect().catch(() => { /* already closed */ })
        };
    },
    ethernetip: async (src, settings) => {
        const lib = global.get("ethernetip");
        if (!lib) throw new Error("EtherNet/IP library is not available (see nodered/settings.js)");
        const { host } = hostPort(src.endpoint, 44818);
        const plc = new lib.Controller(true);           // connected messaging
        plc.timeout_sp = 3000;
        plc.on("error", () => { /* reported by the next read */ });
        // false: do not upload the controller's tag list; atomic tags only.
        await withTimeout(plc.connect(host, Number.isInteger(settings.slot) ? settings.slot : 0, false),
                          OPEN_TIMEOUT_MS, "connect to " + host);
        let tags = null, group = null, groupKey = null;
        return {
            probe: async address => {
                if (!lib.Tag.isValidTagname(address)) throw new Error("not a valid Logix tag name");
                await plc.readTag(new lib.Tag(address));
            },
            read: async addresses => {
                const key = addresses.join("\n");
                if (key !== groupKey) {
                    tags = addresses.map(a => new lib.Tag(a));
                    group = new lib.TagGroup();
                    tags.forEach(t => group.add(t));
                    groupKey = key;
                }
                if (tags.length === 1) await plc.readTag(tags[0]);
                else await plc.readTagGroup(group);
                return tags.map(t => t.value);
            },
            connected: () => !plc.destroyed && plc.established !== false,
            close: () => { try { plc.destroy(); } catch (e) { /* already closed */ } }
        };
    }
};

function same(a, b) {
    return a === b || (typeof a === "object" && JSON.stringify(a) === JSON.stringify(b));
}

function start(src) {
    const settings = src.settings || {};
    const pollMs = Math.max(100, Number(settings.pollIntervalMs) || 1000);
    const st = { name: src.name, signature: src.signature, online: null, stopped: false, conn: null, timer: null };
    sources[src.name] = st;
    st.stop = () => {
        st.stopped = true;
        clearTimeout(st.timer);
        if (st.conn) st.conn.close();
    };
    let attempt = 0;

    async function session() {
        if (st.stopped) return;
        const last = {};                                // address -> last value sent, per connection
        try {
            st.conn = await drivers[src.protocol](src, settings);
            // Probe each address once, so one wrong address cannot stop the others.
            // An address the PLC refuses is published as v null, q bad (step 2.4).
            const good = [], refused = [];
            for (const item of src.items) {
                try {
                    await st.conn.probe(item.address);
                    good.push(item);
                } catch (e) {
                    if (!st.conn.connected()) throw e;
                    node.warn(src.name + ": " + item.address + ": " + describe(e) + " - not read");
                    refused.push(item.address);
                }
            }
            report(st, true);
            attempt = 0;
            for (const address of refused) {
                node.send([{ payload: { source: src.name, address, value: null, status: "BadAddressRefused",
