// Heartbeat and source loss (ADR-0007, step 2.3). Input: a tick every second,
// and every source connection change from acquisition.
// - Tick: a property not published for its max_publish_interval_ms is
//   republished with its latest value, the current time and tss "gateway"
//   (the gateway vouches that the value is still current). A consumer may
//   therefore treat a value older than twice its interval as stale.
// - Source offline: every property of that source is republished at once
//   with its last value (null if it never had one), q "bad" and the time the
//   loss was detected, to the UNS and the historian. While the source stays
//   offline, heartbeats repeat "bad". Back online, fresh values come from
//   acquisition and bring their own quality.
// Outputs: 1 UNS, 2 historian numbers, 3 historian text (as "normalise").
const model = global.get("ofm_model");
if (!model) return null;
const values = global.get("ofm_values") || {};
global.set("ofm_values", values);
const down = global.get("ofm_sources_down") || {};
global.set("ofm_sources_down", down);
const now = Date.now();
const QUALITY = ["good", "uncertain", "bad"];
const uns = [], num = [], txt = [];

function publish(p, v, q) {
    const st = values[p.propertyId] || (values[p.propertyId] = {});
    if (v === undefined) v = null;
    if (v === null) q = "bad";                          // schemas/value: v null only with q bad
    uns.push({ topic: p.topic, payload: { v, ts: now, q, tss: "gateway" }, retain: true, qos: 1 });
    if (p.historised) {                                 // v null is stored as NULL with q bad (migration 010)
        const row = [now, p.propertyId, null, QUALITY.indexOf(q), 1];
        if (p.datatype === "string") { row[2] = v; row[5] = "t"; txt.push({ params: row }); }
        else { row[2] = typeof v === "boolean" ? (v ? 1 : 0) : v; num.push({ params: row }); }
    }
    st.sent = { v, q, at: now };
}

const change = msg.payload && typeof msg.payload === "object" && "online" in msg.payload ? msg.payload : null;
if (change) {
    if (change.online) {
        delete down[change.source];
        return null;
    }
    if (down[change.source]) return null;              // already marked
    down[change.source] = now;
    for (const p of Object.values(model.byProperty)) {
        if (p.source !== change.source) continue;
        const st = values[p.propertyId];
        publish(p, st && st.latest ? st.latest.v : null, "bad");
    }
} else {
    for (const p of Object.values(model.byProperty)) {
        if (!p.source) continue;
        const st = values[p.propertyId];
        if (!st || !st.sent) continue;
        if (!st.latest && !down[p.source]) continue;
        if (now - st.sent.at < (p.maxIntervalMs || 60000)) continue;
        publish(p, st.latest ? st.latest.v : null, down[p.source] ? "bad" : st.latest.q);
    }
}
if (change && uns.length) node.status({ fill: "red", shape: "ring", text: change.source + " lost: " + uns.length + " value(s) marked bad" });
return [uns.length ? uns : null, num.length ? num : null, txt.length ? txt : null];

// One value change in, the canonical OFM messages out (Overview §7.1).
// Output 1: live value to the UNS. Output 2: historian row (numbers, booleans).
// Output 3: historian row (text). Output 4: quarantine and cache status.
const SKEW_MS = 5 * 60 * 1000;                      // ADR-0003: future-skew limit
const OLDEST = Date.UTC(2020, 0, 1);                 // older device time = clock not set
const v = msg.payload;
const model = global.get("ofm_model");
