         ((p.low !== null && p.low !== undefined && value < p.low) ||
          (p.high !== null && p.high !== undefined && value > p.high))) {
    q = worst(q, "uncertain");                       // outside the engineering range
}

// Backwards device time for the same property is a clock problem (ADR-0003).
const last = context.get("lastTs") || {};
if (last[p.propertyId] !== undefined && ts < last[p.propertyId]) q = worst(q, "uncertain");
last[p.propertyId] = Math.max(ts, last[p.propertyId] || 0);
context.set("lastTs", last);

// --- deadband; latest and last published value per property (ADR-0007) --------
// The latest value is kept for the heartbeat and for marking a lost source.
// A number is published when it moves by at least the deadband from the last
// published one; a change of quality is always published. Deadband 0 = every
// value the source reports.
const values = global.get("ofm_values") || {};
global.set("ofm_values", values);
const st = values[p.propertyId] || (values[p.propertyId] = {});
st.latest = { v: value, q, ts, tss };
if (st.sent && st.sent.q === q && p.deadband > 0 && typeof value === "number" &&
    typeof st.sent.v === "number" && Math.abs(value - st.sent.v) < p.deadband) {
    return [null, null, null, null];
}
st.sent = { v: value, q, at: v.receivedAt };

const live = { topic: p.topic, payload: { v: value, ts, q, tss }, retain: true, qos: 1 };

let numeric = null, text = null;
// Historian row; a missing value is stored as NULL with quality bad (migration 010).
// Text rows are marked "t" in a sixth field, because a NULL has no type.
if (p.historised) {
    const row = [ts, p.propertyId, null, ["good", "uncertain", "bad"].indexOf(q), tss === "device" ? 0 : 1];
    if (p.datatype === "string") { row[2] = value; row[5] = "t"; text = { params: row }; }
    else { row[2] = typeof value === "boolean" ? (value ? 1 : 0) : value; numeric = { params: row }; }
