// --- helpers ------------------------------------------------------------------
function qualityOf(status) {
    const s = String(status || "Bad");
    return s.startsWith("Good") ? "good" : s.startsWith("Uncertain") ? "uncertain" : "bad";
}
function worst(a, b) {
    const order = ["good", "uncertain", "bad"];
    return order[Math.max(order.indexOf(a), order.indexOf(b))];
}
function plain(raw) {
    if (raw === null || raw === undefined) return null;
    if (typeof raw === "number" || typeof raw === "boolean") return raw;
    return String(raw).slice(0, 1024);
}
function convert(raw, p) {
    if (raw === null || raw === undefined) return null;
    if (p.datatype === "bool") {
        if (typeof raw === "boolean") return raw;
        if (typeof raw === "number") return raw !== 0;
        return null;
    }
    if (p.datatype === "string") return String(raw).slice(0, 1024);
    let n;
    if (Array.isArray(raw) && raw.length === 2) n = raw[0] * 4294967296 + raw[1];   // 64-bit as [high, low]
    else if (typeof raw === "boolean") n = raw ? 1 : 0;
    else n = Number(raw);
    if (!Number.isFinite(n)) return null;
    n = n * p.factor + p.offset;
    return p.datatype === "int" ? Math.round(n) : n;
}

// Historian writer (ADR-0002, step 2.4). Input: historian rows from
// "normalise and validate" and "heartbeat" ([ts, propertyId, value, quality,
// tsSource, "t" for text]; value NULL only with quality bad), and the 1-second tick.
// - Rows are written in batches: every second, or at once when 500 are waiting.
// - If the database cannot be reached, batches go to a compressed disk queue
//   (OFM_SF_QUEUE_DIR) and are written, oldest first, when it returns. Rows
//   are idempotent (ON CONFLICT DO NOTHING), so a batch written twice is
//   harmless. The queue is limited to OFM_SF_QUEUE_MAX_GB (default 10); when
//   full, the oldest batches are dropped and counted as droppedRows.
// - A row the database refuses as data (e.g. a deleted property) is dropped
//   with a warning, so it can never block the queue.
// - State on ofm/_system/historian/{runtime} (schemas/system-historian):
//   on every change (state or dropped rows), and every 60 s while buffering.
