function pool() {
    if (!st.pool) {
        st.pool = new pg.Pool({
            host: "timescaledb", port: 5432, database: "ofm",
            user: env.get("OFM_RUNTIME_DB_USER"), password: env.get("OFM_RUNTIME_DB_PASSWORD"),
            application_name: "ofm-runtime-historian", max: 2,
            connectionTimeoutMillis: 5000, idleTimeoutMillis: 30000
