    st.files = fs.readdirSync(DIR).filter(f => /^\d+-\d+-\d+\.json\.gz$/.test(f)).sort().map(name => ({
        name, rows: Number(name.split("-")[2].split(".")[0]), bytes: fs.statSync(path.join(DIR, name)).size
    }));
