            fs.writeFileSync(path.join(dir, name + ".tmp"), zlib.gzipSync(JSON.stringify(st.buf)));
            fs.renameSync(path.join(dir, name + ".tmp"), path.join(dir, name));
        } catch (e) { node.error("could not save " + st.buf.length + " row(s): " + e.message); }
        st.buf = [];
    }
    if (st.pool) st.pool.end().catch(() => { /* already closed */ });
}
context.set("st", null);

