// Source connection state, retained, for every consumer (ADR-0007).
const s = msg.payload;
msg.topic = "ofm/_system/sources/" + s.source;
msg.payload = { state: s.online ? "online" : "offline", ts: Date.now() };
if (!s.online && s.error) msg.payload.error = String(s.error).slice(0, 1024);
msg.retain = true;
